ALTER TABLE "SchoolSetting" ADD COLUMN "analyticsPolicy" JSONB;
CREATE TABLE "AnalyticsSnapshot" ("id" TEXT PRIMARY KEY,"schoolId" TEXT NOT NULL REFERENCES "School"("id") ON DELETE CASCADE,"actorId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"permissionKey" TEXT NOT NULL,"filters" JSONB NOT NULL,"data" JSONB NOT NULL,"asOf" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"expiresAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "AnalyticsSnapshot_schoolId_actorId_expiresAt_idx" ON "AnalyticsSnapshot"("schoolId","actorId","expiresAt");
CREATE TABLE "AnalyticsExportJob" ("id" TEXT PRIMARY KEY,"schoolId" TEXT NOT NULL REFERENCES "School"("id") ON DELETE CASCADE,"actorId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"snapshotId" TEXT NOT NULL,"format" TEXT NOT NULL,"template" TEXT NOT NULL,"options" JSONB NOT NULL,"status" TEXT NOT NULL DEFAULT 'QUEUED',"fileKey" TEXT,"size" INTEGER,"error" TEXT,"leaseToken" TEXT,"leaseUntil" TIMESTAMP(3),"attempts" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "AnalyticsExportJob_schoolId_actorId_createdAt_idx" ON "AnalyticsExportJob"("schoolId","actorId","createdAt");CREATE INDEX "AnalyticsExportJob_status_leaseUntil_idx" ON "AnalyticsExportJob"("status","leaseUntil");
CREATE TABLE "AnalyticsAttentionCase" ("id" TEXT PRIMARY KEY,"schoolId" TEXT NOT NULL REFERENCES "School"("id") ON DELETE CASCADE,"academicYearId" TEXT NOT NULL REFERENCES "AcademicYear"("id") ON DELETE RESTRICT,"enrollmentId" TEXT NOT NULL REFERENCES "StudentEnrollment"("id") ON DELETE RESTRICT,"indicator" TEXT NOT NULL,"evidence" JSONB NOT NULL,"severity" TEXT NOT NULL,"ownerId" TEXT REFERENCES "User"("id") ON DELETE SET NULL,"status" TEXT NOT NULL DEFAULT 'OPEN',"dueDate" DATE,"revision" INTEGER NOT NULL DEFAULT 1,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "AnalyticsAttentionCase_scope_key" ON "AnalyticsAttentionCase"("schoolId","academicYearId","enrollmentId","indicator");CREATE INDEX "AnalyticsAttentionCase_schoolId_academicYearId_status_idx" ON "AnalyticsAttentionCase"("schoolId","academicYearId","status");
CREATE TABLE "AnalyticsCaseEvent" ("id" TEXT PRIMARY KEY,"caseId" TEXT NOT NULL REFERENCES "AnalyticsAttentionCase"("id") ON DELETE CASCADE,"actorId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE RESTRICT,"action" TEXT NOT NULL,"note" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "AnalyticsCaseEvent_caseId_createdAt_idx" ON "AnalyticsCaseEvent"("caseId","createdAt");
CREATE INDEX "Homework_report_cohort_idx" ON "Homework"("schoolId","academicYearId","dueAt","status");
CREATE INDEX "StudentMark_enrollmentId_idx" ON "StudentMark"("enrollmentId");
INSERT INTO "Permission"("id","code","module","action","description","updatedAt") VALUES ('davi-report-export','REPORT_EXPORT','Reports','export','Generate and download private analytics reports',CURRENT_TIMESTAMP),('davi-report-attention-view','REPORT_ATTENTION_VIEW','Reports','attention.view','View private student attention evidence',CURRENT_TIMESTAMP),('davi-report-attention-manage','REPORT_ATTENTION_MANAGE','Reports','attention.manage','Manage attention follow-up records',CURRENT_TIMESTAMP),('davi-report-ai-review','REPORT_AI_REVIEW','Reports','ai.review','Approve advisory analytics insights',CURRENT_TIMESTAMP) ON CONFLICT ("code") DO NOTHING;
